function calculatePay(hours, hourlyRate) {
  return hours * hourlyRate;
}

function getArea(width, height) {
  if (width <= 0 || height <= 0) return 0;
  return width * height;
}

function getFinalPrice(price, discount, point) {
  return price - discount - point;
}
